def _header_value(headers, wanted):
    """Return one HTTP header value, treating header names case-insensitively."""
    try:
        values = [
            value
            for name, value in headers.items()
            if isinstance(name, str) and name.lower() == wanted
        ]
    except (AttributeError, TypeError, ValueError):
        raise InvalidNotification("malformed headers") from None

    if len(values) != 1 or not isinstance(values[0], str):
        raise InvalidNotification("missing or duplicate header")
    return values[0]


def _invalid_json_constant(value):
    # json.loads otherwise accepts the non-JSON values NaN and Infinity.
    raise ValueError("invalid JSON constant")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    try:
        if not isinstance(raw_body, bytes):
            raise InvalidNotification("body must be bytes")

        timestamp_text = _header_value(headers, _TIMESTAMP_HEADER)
        if not timestamp_text or any(ch < "0" or ch > "9" for ch in timestamp_text):
            raise InvalidNotification("malformed timestamp")
        timestamp = int(timestamp_text)
        if abs(timestamp - now) > 300:
            raise InvalidNotification("stale timestamp")

        signature = _header_value(headers, _SIGNATURE_HEADER)
        digest_text = signature[3:] if signature.startswith("v1=") else ""
        if len(digest_text) != 64 or any(ch not in _HEX_DIGITS for ch in digest_text):
            raise InvalidNotification("malformed signature")

        supplied_digest = bytes.fromhex(digest_text)
        signed_data = timestamp_text.encode("ascii") + b"." + raw_body
        expected_digest = hmac.new(secret, signed_data, hashlib.sha256).digest()
        if not hmac.compare_digest(supplied_digest, expected_digest):
            raise InvalidNotification("signature mismatch")

        text = raw_body.decode("utf-8")
        event = json.loads(text, parse_constant=_invalid_json_constant)
        if not isinstance(event, dict):
            raise InvalidNotification("body must be a JSON object")

